static long cal(int index, int last, int hasPair, String s, long[] cost) {
    if (index == s.length()) {
        return hasPair == 1 ? 0 : MAX;
    }
    if (dp[last][hasPair][index] != -1) {
        return dp[last][hasPair][index];
    }
    int cur = s.charAt(index) - '0';
    long res = cal(index + 1, cur, hasPair, s, cost);
    if (cur == last) {
        hasPair = 1;
    }
    if (hasPair == 0) {
        long tmp = cal(index + 1, last, 1, s, cost);
        if (tmp != MAX) {
            tmp += (cur != last ? cost[index] : 0);
        }
        res = Long.min(res, tmp);
    }
    return dp[last][hasPair][index] = res;
}
